# ------------------------------------------------------------ 1 HTML and CSS

html = Lab('web_lab_htmlcss', 1, 'HTML and CSS Studio', 'techOffice',
    'Lay out grids and type scales, write semantic markup to a brief, review CSS and build a specificity calculator to debug the cascade.',
    ['Write semantic, accessible HTML', 'Plan layout grids and type', 'Understand and debug the cascade'],
    ['cs_web'], 'wh',
    problems=[
        D('grid', 'Layout grid for the new site', 'Design a 12-column grid. Column width = (container − 11 gutters) ÷ 12.',
          [I('w', 'Container width', 600, 1600, 20, 1600, 'px'), I('g', 'Gutter', 8, 48, 4, 48, 'px')],
          [O('C', 'Column width', '(w-11*g)/12', 'px', 1), O('L', 'Line length in a 6-column block at 18 px text', '(6*(w-11*g)/12+5*g)/(18*0.5)', 'characters', 0)],
          {'w': 1600, 'g': 48}, ['C', 'L'],
          ([le('L', 75, 'Readable line length: at most 75 characters')], [ge('L', 45, 'At least 45 characters per line'), ge('g', 16, 'Gutters at least 16 px')], [ge('C', 60, 'Columns at least 60 px wide'), ge('w', 1000, 'Container at least 1,000 px')]),
          {'w': 1080, 'g': 24}),
        D('type', 'Type scale', 'Choose a base size and modular scale ratio; h1 = base × ratio⁴, h2 = base × ratio³.',
          [I('b', 'Base font size', 12, 22, 1, 12, 'px'), I('r', 'Scale ratio', 1.1, 1.8, 0.05, 1.8)],
          [O('H', 'h1 size', 'b*r^4', 'px', 1), O('K', 'h2 size', 'b*r^3', 'px', 1)],
          {'b': 12, 'r': 1.8}, ['H', 'K'],
          ([ge('b', 16, 'Body text at least 16 px')], [le('H', 48, 'h1 no larger than 48 px (fits mobile)')], [ge('K', 28, 'h2 at least 28 px (clear hierarchy)')]),
          {'b': 16, 'r': 1.3}),
    ],
    code=[
        Code('specificity', 'Cascade debugger', 'Ticket WEB-31: designers keep asking why their CSS is ignored. Build a specificity tool.', [
            V3('The starting program ignores attributes and pseudo-classes. Input: one selector per line. Print "selector: (a,b,c)" — a = IDs, b = classes, attributes and pseudo-classes, c = type selectors and pseudo-elements.',
               [('#nav .item a\nul li a:hover\nbutton.primary[disabled]\np::first-line\n.card > h2', '#nav .item a: (1,1,1)\nul li a:hover: (0,1,3)\nbutton.primary[disabled]: (0,2,1)\np::first-line: (0,0,2)\n.card > h2: (0,1,1)'),
                ('div', 'div: (0,0,1)'), ('#a #b', '#a #b: (2,0,0)')], M['spec1'], None, M['spec1_bug']),
            V3('Input: two selectors. Print "X wins" for the more specific, or "tie: second wins (later in source)".',
               [('#main p\n.content .intro p', '#main p wins'), ('.btn.primary\n.btn.secondary', 'tie: .btn.secondary wins (later in source)'), ('p\nbody p', 'body p wins')], M['spec2']),
            V3('Resolve the colour property. Input lines "selector | value" (value may end with !important), all matching the same element, in source order. Print "color: value (from selector)" adding " !important" when that decided it.',
               [('p | black\n.note | blue\n#warn | red\np | green !important', 'color: green (from p !important)'), ('.a | red\n.b | blue', 'color: blue (from .b)'), ('#x | red\n.y | blue\n.y.z | teal', 'color: red (from #x)')], M['spec3']),
        ], skills=['cs_web']),
    ],
    cases=[
        case('semantic', 'Semantic markup for a charity homepage', 'Rebuild the homepage of Riverside Food Bank with semantic, accessible HTML.', 'Current markup issues',
             [('fix', 'Fix?', ['Fix', 'Fine'])],
             [('Div soup', 'Navigation is <div class="nav"> with <span onclick> links.', {'fix': 'Fix'}, 'Use <nav> and real <a> links so keyboards work.', True), ('Images', 'Hero image has no alt text.', {'fix': 'Fix'}),
              ('Headings', 'One <h1>, then <h2> sections.', {'fix': 'Fine'}), ('Form', 'Donate form inputs have no labels.', {'fix': 'Fix'})],
             'Grace Okoye, charity manager', 'Our volunteers using screen readers say the site is impossible.',
             [('E', 'Can we use proper <nav>, <main> and <a> elements?', 'Whatever works for everyone.'),
              ('E', 'Can you give me alt text for the photos?', 'Yes — I’ll describe each.'),
              ('U', 'Which pages are used most?', 'Donate and volunteer.'),
              ('N', 'Do you like the logo?', 'Love it.'),
              ('P', 'Can we keep the clickable spans and add ARIA later?', 'Is that OK?', 'Native elements give keyboard and screen-reader support for free.')],
             conclusions=[Choice('rule', 'First rule of ARIA', 'use a native HTML element when one exists', ['add ARIA to every div', 'avoid HTML elements'])],
             doc=('Homepage markup', [
                 ('Header and navigation', [('Uses <nav>', [r'<nav']), ('Uses real links', [r'<a\s+href='])],
                  '<header><a href="/">Riverside Food Bank</a><nav aria-label="Main"><ul><li><a href="/donate">Donate</a></li><li><a href="/volunteer">Volunteer</a></li><li><a href="/contact">Contact</a></li></ul></nav></header>'),
                 ('Main content', [('Uses <main> and <h1>', [r'<main[\s>][\s\S]*<h1']), ('Image has alt text', [r'<img[^>]+alt="[^"]+"']), ('Labelled input', [r'<label[^>]+for='])],
                  '<main><h1>Help us feed families in Riverside</h1><img src="volunteers.jpg" alt="Volunteers packing food parcels"><form><label for="amount">Donation amount</label><input id="amount" name="amount" type="number"><button>Donate</button></form></main>')])),
        case('cssreview', 'CSS code review', 'Review a pull request that restyles the product cards.', 'CSS changes',
             [('ok', 'Verdict', ['Approve', 'Change'])],
             [('Important', '.card { color: red !important; } used on 30 rules.', {'ok': 'Change'}, 'Overusing !important breaks the cascade.'), ('Height', '.card { height: 320px; } with variable-length text.', {'ok': 'Change'}, 'Fixed heights clip content when text grows or zooms.'),
              ('Custom props', 'Colours moved into CSS custom properties.', {'ok': 'Approve'}), ('Grid', 'Cards laid out with CSS grid and minmax().', {'ok': 'Approve'})],
             'Dan Fry, front-end developer', 'Can you approve my card styles?',
             [('E', 'Can we drop !important and fix the specificity instead?', 'Sure, I’ll refactor.'),
              ('E', 'Can the card height grow with content (min-height)?', 'Yes, good catch.'),
              ('U', 'Did you test at 200% zoom?', 'Not yet.'),
              ('N', 'Which editor do you use?', 'VS Code.'),
              ('P', 'Approve now, we’ll fix later?', 'Later never comes.', 'Fix maintainability issues in review.')],
             conclusions=[Choice('why', 'Why avoid fixed heights on text containers?', 'Text overflows when content or zoom grows', ['They load slowly', 'Browsers ignore them'])]),
    ])

# ------------------------------------------------------------ 2 JavaScript

js = Lab('web_lab_js', 2, 'JavaScript Development', 'computingLab',
    'Implement shopping-cart logic, form validation and event timing (debounce and throttle) in JavaScript or Python, and fix real JS bugs.',
    ['Use arrays, objects and string handling', 'Validate user input', 'Reason about events and timing'],
    ['cs_web', 'cs_prog'], 'wj',
    code=[
        Code('cart', 'Shopping cart logic', 'Ticket SHOP-4: the cart total is wrong in production.', [
            V3('The starting JavaScript concatenates strings instead of adding numbers. Input lines "item,qty,price". Print "Total: x" (2 dp).',
               [('pen,3,1.50\npad,2,2.25', 'Total: 9.00'), ('desk,1,120', 'Total: 120.00'), ('a,10,0.10\nb,4,0.25', 'Total: 2.00')], M['cart1'], J['cart1'], None, J['cart1_bug']),
            V3('Bulk discounts: 5% off a line with 5–9 units, 10% off 10 or more. Print each "item: line total" then "Total: x" (2 dp).',
               [('pen,12,1.00\npad,5,2.00\nink,1,3.00', 'pen: 10.80\npad: 9.50\nink: 3.00\nTotal: 23.30'), ('a,4,10', 'a: 40.00\nTotal: 40.00'), ('b,9,1\nc,10,1', 'b: 8.55\nc: 9.00\nTotal: 17.55')], M['cart2'], J['cart2']),
            V3('Stock check. Line 1 stock "item,qty;item,qty". Then cart lines "item,qty" processed in order: reserve if enough stock, else print "item: only n in stock". Then "Checkout OK" or "Checkout blocked".',
               [('pen,10;pad,2\npen,4\npad,3\npen,6', 'pen: reserved 4\npad: only 2 in stock\npen: reserved 6\nCheckout blocked'), ('a,1\na,1', 'a: reserved 1\nCheckout OK'), ('a,1\nb,1', 'b: only 0 in stock\nCheckout blocked')], M['cart3'], J['cart3']),
        ], skills=['cs_web', 'cs_prog']),
        Code('forms', 'Sign-up form validation', 'Ticket SHOP-9: validate the registration form before it reaches the server.', [
            V3('For each line print "email: valid" or "email: invalid" (trim spaces). Valid: something@something.tld with a TLD of 2+ letters and no spaces.',
               [('ana@example.com\nbad@\nx@y.z\n jo.lee+news@mail.co.uk ', 'ana@example.com: valid\nbad@: invalid\nx@y.z: invalid\njo.lee+news@mail.co.uk: valid'), ('a b@c.de', 'a b@c.de: invalid'), ('q@w.io', 'q@w.io: valid')], M['val1'], J['val1']),
            V3('The starting program uses an 8-character rule and skips the match check. Line 1 password, line 2 confirmation. Print each error: "Password must be at least 12 characters", "Passwords do not match"; or OK.',
               [('short\nshort', 'Password must be at least 12 characters'), ('longenough1234\nlongenough1235', 'Passwords do not match'), ('longenough1234\nlongenough1234', 'OK'), ('abcdefghi\nx', 'Password must be at least 12 characters\nPasswords do not match')], M['val2'], J['val2'], None, J['val2_bug']),
            V3('Input lines "field=value" for name, email, postcode, age. Print an error per invalid field in that order — "name: required", "email: enter a valid email address", "postcode: enter a valid UK postcode" (e.g. SW1A 1AA, case-insensitive), "age: must be a whole number from 16 to 120" — or "Form valid".',
               [('name=Ana\nemail=ana@x.com\npostcode=sw1a 1aa\nage=30', 'Form valid'), ('name=\nemail=nope\npostcode=12345\nage=15', 'name: required\nemail: enter a valid email address\npostcode: enter a valid UK postcode\nage: must be a whole number from 16 to 120'),
                ('name=Bo\nemail=bo@b.com\npostcode=M1 1AE\nage=abc', 'age: must be a whole number from 16 to 120')], M['val3'], J['val3']),
        ], skills=['cs_web']),
        Code('events', 'Event timing', 'Ticket SHOP-12: the search box sends a request on every keystroke.', [
            V3('Input: a list of event names. Print each event type with its count, alphabetically: "type: n".',
               [('click scroll click key click', 'click: 3\nkey: 1\nscroll: 1'), ('key', 'key: 1'), ('b a b', 'a: 1\nb: 2')], M['deb1'], J['deb1']),
            V3('Debounce. Line 1 delay d ms, line 2 keystroke times. The search fires d ms after a keystroke only if no other keystroke comes within d ms. Print "Search fired at: …" and "Requests saved: n".',
               [('300\n0 100 250 700 1200 1300', 'Search fired at: 550 1000 1600\nRequests saved: 3'), ('100\n0', 'Search fired at: 100\nRequests saved: 0'), ('50\n0 50 100', 'Search fired at: 50 100 150\nRequests saved: 0')], M['deb2'], J['deb2']),
            V3('Throttle a scroll handler. Line 1 interval w ms, line 2 event times. The handler runs on an event only if at least w ms have passed since it last ran. Print "Handler ran at: …" and "Calls dropped: n".',
               [('100\n0 30 60 120 150 260', 'Handler ran at: 0 120 260\nCalls dropped: 3'), ('10\n0 10 20', 'Handler ran at: 0 10 20\nCalls dropped: 0'), ('1000\n5 6 7', 'Handler ran at: 5\nCalls dropped: 2')], M['deb3'], J['deb3']),
        ], skills=['cs_web', 'cs_prog']),
    ],
    cases=[
        case('bugs', 'JavaScript bug triage', 'Triage front-end bug reports with the code snippets attached.', 'Bug reports',
             [('cause', 'Cause', ['Type coercion', 'Async timing', 'Scope/closure', 'Not a bug'])],
             [('Quantity', '`if (qty == "0")` treats an empty string as zero.', {'cause': 'Type coercion'}, 'Use === and convert inputs explicitly.'), ('Undefined', '`const user = fetch(url); console.log(user.name)` prints undefined.', {'cause': 'Async timing'}),
              ('Loop', '`for (var i…) setTimeout(() => log(i))` logs the same number five times.', {'cause': 'Scope/closure'}), ('Design', 'The button is blue instead of green, as designed.', {'cause': 'Not a bug'})],
             LEAD, 'Three bugs from QA. What’s going on?',
             [('E', 'Can we await the fetch and handle errors?', 'Yes, with try/catch.'),
              ('E', 'Can we switch the loop to let?', 'Yes, block scope fixes it.'),
              ('U', 'Is there a linter rule for ==?', 'eqeqeq — let’s enable it.'),
              ('N', 'Which browser do you prefer?', 'Firefox.'),
              ('P', 'Wrap everything in setTimeout until it works?', 'That hides the problem.', 'Timing hacks create flaky bugs.')],
             conclusions=[Choice('fetch', 'Fix for the fetch bug', 'await the promise (and parse the JSON) before using the data', ['add a longer timeout', 'use var'])]),
    ],
    investigations=[
        V('leak', 'Dashboard tab gets slower all day', 'Support staff say the web dashboard becomes unusable after a few hours open.',
          [('Memory grows by ~40 MB per hour in the browser’s performance monitor.', True), ('Each auto-refresh adds a new scroll event listener without removing the old one.', True), ('After 8 hours there are 480 listeners on the window.', True),
           ('The dashboard uses a dark theme.', False), ('Staff use 24-inch monitors.', False)],
          'Memory leak from event listeners added on every refresh and never removed', ['The dark theme', 'Large monitors', 'Slow Wi-Fi'],
          'Add the listener once (or remove it on refresh/unmount), then profile to confirm memory is flat', ['Ask staff to refresh hourly', 'Buy more RAM', 'Remove the dashboard'],
          calc=('One refresh per minute for 8 hours: how many listeners?', 480, 'listeners', '8 × 60 = 480.'),
          steps=['Record a memory profile', 'Find objects that keep growing', 'Remove listeners on refresh or add them once', 'Re-profile over several hours', 'Release the fix'],
          must=[(0, 1), (1, 2), (2, 3), (3, 4)]),
    ])

